//! Evaluates directional decisions against future prices at fixed horizons.
use score_engine::Decision;
#[derive(Debug,Clone,PartialEq)]pub struct PendingOutcome{pub symbol:String,pub decision:Decision,pub decided_at_millis:i64,pub entry_price:f64}
#[derive(Debug,Clone,PartialEq)]pub struct Outcome{pub symbol:String,pub decision:String,pub decided_at_millis:i64,pub horizon_minutes:i32,pub entry_price:f64,pub exit_price:f64,pub return_pct:f64,pub directional_return_pct:f64,pub correct:bool,pub evaluated_at_millis:i64}
pub fn evaluate(p:&PendingOutcome,exit_price:f64,horizon_minutes:i32,evaluated_at_millis:i64)->Option<Outcome>{if p.entry_price<=0.0||exit_price<=0.0{return None;}let direction=match p.decision{Decision::StrongLong|Decision::Long=>1.0,Decision::StrongShort|Decision::Short=>-1.0,_=>return None};let return_pct=(exit_price/p.entry_price-1.0)*100.0;let directional_return_pct=return_pct*direction;Some(Outcome{symbol:p.symbol.clone(),decision:format!("{:?}",p.decision),decided_at_millis:p.decided_at_millis,horizon_minutes,entry_price:p.entry_price,exit_price,return_pct,directional_return_pct,correct:directional_return_pct>0.0,evaluated_at_millis})}
#[cfg(test)]mod tests{use super::*;#[test]fn long_profit_is_correct(){let p=PendingOutcome{symbol:"BTCUSDT".into(),decision:Decision::Long,decided_at_millis:0,entry_price:100.0};let o=evaluate(&p,105.0,60,3_600_000).unwrap();assert!(o.correct);assert!(o.directional_return_pct>0.0);}#[test]fn short_profit_is_correct(){let p=PendingOutcome{symbol:"BTCUSDT".into(),decision:Decision::Short,decided_at_millis:0,entry_price:100.0};assert!(evaluate(&p,95.0,60,3_600_000).unwrap().correct);}#[test]fn neutral_is_not_evaluated(){let p=PendingOutcome{symbol:"BTCUSDT".into(),decision:Decision::Neutral,decided_at_millis:0,entry_price:100.0};assert!(evaluate(&p,101.0,15,900_000).is_none());}}
